-- ScholarBridgeAi — Scholarship rewrite pass 41 (Chile)
-- Verified 2026-10-25 against the providers' own pages (cited in source_url).
-- Chile funds outward mobility, not inward: Becas Chile pays Chilean citizens to study abroad,
-- AGCID and the OAS schemes are for Latin America and the OAS member states, and the universities'
-- own aid lines are tied to Chilean admission instruments. One row is retired, one is re-pointed at
-- the postgraduate benefits that do exist. Values are in CLP; amount_usd_value stays 0.

-- 695 Pontificia Universidad Catolica de Chile — retired: its foreign-student scholarships are for exchange students
UPDATE scholarships SET
  title = 'Pontificia Universidad Catolica de Chile - foreign-student scholarships are for exchange students (retired)',
  description = 'The Pontifical Catholic University of Chile answers the international scholarship question on its own page and the answer is narrower than the old record implied. Asked whether there are scholarships for foreigners at UC, the university replies that if you are an exchange student it has tuition scholarships for Latin American Catholic universities, for the CINDA network and for Chilean Catholic universities - which is an exchange programme for students already enrolled elsewhere in Latin America, not an entrance award for a degree-seeking applicant from Uzbekistan. On the postgraduate side the same site states flatly that UC has no institutionally funded postgraduate tuition scholarships and that candidates should look at external scholarships and bank loans instead. The university own funding lines are tied to Chilean admission instruments: the Beca Cristobal Conde requires Chilean nationality and admission through the 2026 process, the Beca Familia UC requires simultaneous enrolment of siblings, and the rest are built around the PAES admission test, the Registro Social de Hogares and MINEDUC state benefits. A degree-seeking international student therefore pays the full arancel, published in the range of roughly CLP 5,500,000 to CLP 9,500,000 a year depending on the programme, plus a one-off matricula right of CLP 195,000 for 2026. The old record claimed a USD 14,000 UC International Undergraduate Scholarship with an August to September deadline; no such award is published.',
  coverage_type = 'Unspecified', award_basis = 'variable', award_amount = NULL, award_currency = 'CLP', amount_usd_value = 0,
  deadline = 'Not published', deadline_date = NULL, deadline_type = 'not_published',
  website_url = 'https://www.uc.cl/informacion-para/futuros-estudiantes/',
  source_url = 'https://www.uc.cl/informacion-para/futuros-estudiantes/',
  verification_status = 'verified', source_reliability = 9, is_active = false,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Retired after reading three Pontificia Universidad Catolica de Chile own pages on 2026-10-25: the prospective students page at uc.cl answers the question whether there are scholarships for foreigners in the UC by stating that exchange students have tuition scholarships for Latin American Catholic universities, the CINDA network and Chilean Catholic universities, and lists the UC funding lines as academic excellence prizes, tuition scholarships, Ministry of Education scholarships and external scholarships; the students information page states that UC has no institutionally funded postgraduate tuition scholarships and that external scholarships and bank loans are the alternatives; the admissions funding pages describe the Beca Cristobal Conde as requiring Chilean nationality and admission in the 2026 process, the Beca Familia UC as requiring two or more siblings enrolled simultaneously, the Beneficio de Arancel Parcial and the Beneficio Rebaja Arancelaria as tied to enrolled students in their final semester, and give the one-off matricula right of CLP 195,000 for 2026. The former row claimed a USD 14,000 UC International Undergraduate Scholarship with an August and September deadline and all three degree levels. No award of that description is published, so the row is deactivated rather than repriced, and the exchange-only nature of the foreigner scholarships is recorded so that an applicant from Uzbekistan does not plan around it.'
WHERE id = 695;

-- 710 Universidad de Chile — postgraduate benefits that actually exist, and the entrance routes that do not
UPDATE scholarships SET
  title = 'Universidad de Chile Doctoral Stipend and Postgraduate Tuition Rebates',
  description = 'Chile funds outward mobility rather than inward, and the University of Chile is a clear example. The entrance scholarships it lists for foreigners are closed to an applicant from Uzbekistan: the OAS academic scholarship is for nationals of Organisation of American States member states, the Nelson Mandela master''s programme covers only Angola, Mozambique and South Africa, and the AGCID schemes are built for Latin America. What does exist is in-programme support once a student is enrolled. The Beca de Doctorado de la Universidad de Chile pays CLP 900,000 a month for twelve months, from March to the following February, and to apply you must be a regular first or second-year doctoral student in a University of Chile programme and must also have applied to the national ANID doctoral competition - so it tops up a student already inside, it does not open the door. Beyond that, the faculties run tuition rebates for doctoral and master''s students worth 50, 75, 90 or 100 per cent of the annual programme tuition, deducted directly from the student''s fee account, and several faculty schemes are explicitly open to Chilean and foreign students alike, such as the SYLFF-UChile programme for the master''s in management and public policy, which covers tuition and maintenance with a December application window. The practical conclusion for a student from Uzbekistan is that the University of Chile is a pay-first destination: the doctoral programme in mining engineering, for example, publishes tuition of 800 UF, about USD 32,000, plus an annual matricula of CLP 243,900 and 6 UF for each semester beyond the nominal duration.',
  requirements = 'Be a regular student already enrolled in a doctoral or master''s programme at the University of Chile, since the benefits described here are in-programme rather than entrance awards. For the Beca de Doctorado de la Universidad de Chile, be in the first or second year of a doctoral programme, have applied to the national ANID doctoral scholarship competition, and hold no other source of funding, national or international. For the faculty tuition rebates, apply within the faculty deadline for the year, with fees and any debt regularised, since the University requires payments to be up to date before a rebate can be granted. For the SYLFF-UChile programme, be a professional admitted to the master''s in management and public policy and apply in December. Note that the OAS scholarship requires nationality of an OAS member state, the Nelson Mandela programme covers Angola, Mozambique and South Africa only, and the AGCID schemes target Latin America, so none of them is open to an applicant from Uzbekistan.',
  coverage_type = 'Living Stipend', award_basis = 'fixed', award_amount = 900000, award_currency = 'CLP', award_period = 'month',
  degree_levels = '["Master''s","PhD"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Institutional doctoral stipend and tuition rebates',
  tuition_coverage = 'A doctoral stipend of CLP 900,000 a month for twelve months for students already enrolled in years one or two, plus faculty tuition rebates of 50, 75, 90 or 100 per cent of the annual programme tuition. No entrance scholarship for international applicants is published.',
  english_requirements = 'The benefits set no separate English score; the language requirement of the chosen programme applies, and most University of Chile postgraduate teaching is in Spanish.',
  required_documents = '["Proof of enrolment as a regular doctoral or master''s student","ANID doctoral competition application for the Beca de Doctorado","Academic transcript and supervisor or programme director endorsement","Fee payment receipts and proof that no debt is outstanding","Faculty rebate application within the published deadline"]',
  deadline = 'The doctoral stipend is awarded for March to February; faculty rebate windows are published by each faculty, and the SYLFF-UChile programme applies in December',
  deadline_date = NULL, deadline_type = 'annual', application_status = 'open',
  expected_deadline_period = 'Each faculty publishes its own rebate window, and the central doctoral stipend is tied to the academic year that runs from March to February.',
  website_url = 'https://uchile.cl/postgrado-y-postitulo/departamento-de-postgrado-y-postitulo/ayudas-y-financiamientos/beca-de-doctorado-uchile',
  source_url = 'https://uchile.cl/postgrado-y-postitulo/departamento-de-postgrado-y-postitulo/ayudas-y-financiamientos/beca-de-doctorado-uchile',
  application_url = 'https://uchile.cl/postgrado-y-postitulo/informacion-para-postulantes/opciones-financiamiento',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from University of Chile own pages read on 2026-10-25: the Beca de Doctorado de la Universidad de Chile page states that the stipend for the 2026 academic period is CLP 900,000 a month for twelve months from March 2026 to February 2027, that renewal requires timely progress certified by the graduate school director, that applicants must be regular first or second-year doctoral students, must have applied to the last ANID national doctoral competition, and must not hold another source of national or international funding; the faculty pages describe tuition rebates for doctoral and master students of 50, 75, 90 and 100 per cent of the annual programme tuition deducted from the fee account, and the Faculty of Social Sciences page states that its schemes are aimed at Chilean and foreign students admitted to a University of Chile postgraduate programme, including the SYLFF-UChile programme with a December application period and coverage of tuition, matricula and maintenance; the Faculty of Physical and Mathematical Sciences postgraduate scholarship page lists the OAS academic scholarship for nationals of OAS member states and the Nelson Mandela master programme for Angola, Mozambique and South Africa only, plus AGCID schemes for Latin America; the mining engineering doctoral page publishes tuition of 800 UF, about USD 32,000, an annual matricula of CLP 243,900 for 2026 and 6 UF per semester beyond the nominal duration. CORRECTIONS: the row was titled Universidad de Chile Scholarships for International Students, carried an invented USD 2,250, claimed all three degree levels and gave an August to October deadline. No such entrance scholarship is published; the record now describes the doctoral stipend and the faculty tuition rebates that do exist, states that they are in-programme benefits for enrolled students, and records that the entrance routes for foreigners are closed to applicants from Uzbekistan. award_amount carries the published CLP 900,000 monthly doctoral stipend.'
WHERE id = 710;

-- university_scholarships cards
UPDATE university_scholarships u SET scholarship_name = v.name, availability_status = v.avail, funding_type = v.ftype, max_scholarship = v.mx, covers_tuition = v.tuition, covers_living_expenses = v.living, eligibility_notes = v.elig, official_url = v.url, source_url = v.url, verification_status = 'verified', last_verified_at = now()
FROM (VALUES
  (86, 'Pontificia Universidad Catolica de Chile - foreign-student scholarships are for exchange students', 'No', 'Not applicable', 'No entrance scholarship for degree-seeking international students', false, false, 'UC states that its scholarships for foreigners are for exchange students from Latin American Catholic universities, the CINDA network and Chilean Catholic universities, and that it has no institutionally funded postgraduate tuition scholarships. Its own aid lines require Chilean nationality or admission through the PAES test. International students pay full tuition of roughly CLP 5,500,000 to 9,500,000 a year plus a CLP 195,000 matricula right.', 'https://www.uc.cl/informacion-para/futuros-estudiantes/'),
  (274, 'Universidad de Chile Doctoral Stipend and Postgraduate Tuition Rebates', 'Yes', 'Institutional doctoral stipend and tuition rebates', 'CLP 900,000 a month for twelve months plus 50-100% tuition rebates', true, true, 'In-programme benefits for students already enrolled: the doctoral stipend requires being a regular first or second-year doctoral student and having applied to the ANID competition, and the faculty rebates run from 50 to 100 per cent of annual tuition. The OAS, Nelson Mandela and AGCID entrance schemes are closed to applicants from Uzbekistan.', 'https://uchile.cl/postgrado-y-postitulo/departamento-de-postgrado-y-postitulo/ayudas-y-financiamientos/beca-de-doctorado-uchile')
) AS v(id, name, avail, ftype, mx, tuition, living, elig, url)
WHERE u.id = v.id;
